@@ -0,0 +1,42 @@
+// Picks the response language from a request's Accept-Language header.
+import { LANGUAGES } from "../i18n/messages.js";
+
+/** The supported language the `Accept-Language` value `header` prefers (q-values, region tags), or `fallback`. */
+export function pickLanguage(header, fallback) {
+  if (typeof header !== "string") return fallback;
+  const ranges = [];
+  for (const part of header.split(",")) {
+    const [tag, ...params] = part.split(";").map((s) => s.trim().toLowerCase());
+    if (!tag) continue;
+    let q = 1;
+    const qParam = params.find((p) => /^q\s*=/.test(p));
+    if (qParam !== undefined) {
+      const raw = qParam.replace(/^q\s*=\s*/, "");
+      if (!/^(0(\.\d{0,3})?|1(\.0{0,3})?)$/.test(raw)) continue;
+      q = Number(raw);
+    }
+    const lang = tag === "*" ? "*" : tag.split("-")[0];
+    if (lang !== "*" && !LANGUAGES.includes(lang)) continue;
+    ranges.push({ lang, q, exact: tag === lang });
+  }
+  // A language's weight comes from its plain tag ("ko") when given, else from its best region tag ("ko-KR").
+  const weights = new Map();
+  for (const r of ranges) {
+    const seen = weights.get(r.lang);
+    if (!seen || (r.exact && !seen.exact) || (r.exact === seen.exact && r.q > seen.q)) weights.set(r.lang, r);
+  }
+  const star = weights.get("*");
+  let best = null;
+  let bestQ = 0;
+  for (const [lang, r] of weights) {
+    if (lang !== "*" && r.q > bestQ) {
+      best = lang;
+      bestQ = r.q;
+    }
+  }
+  if (star && star.q > bestQ) {
+    const open = [fallback, ...LANGUAGES].find((l) => !weights.has(l));
+    if (open) return open;
+  }
+  return best ?? fallback;
+}
